<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Http\Requests\Api\StoreDonationRequest; use App\Http\Resources\DonationResource; use App\Models\Donation; use App\Services\{ActivityService,AlertService}; use Illuminate\Http\Request;
class DonationController extends Controller { public function index(Request $r){$q=Donation::with('donor')->filter($r->all());$role=$r->user()->role;if($role==='donor'){$q->where('donor_id',$r->user()->id);}elseif(!in_array($role,['admin','staff','beneficiary'],true)){abort(403);}return DonationResource::collection($q->latest()->paginate(20));} private function data(StoreDonationRequest $r):array{$d=$r->validated();if($r->hasFile('image'))$d['image_path']=$r->file('image')->store('donations','public');unset($d['image']);return $d;} public function store(StoreDonationRequest $r){$this->authorize('create',Donation::class);$d=$r->user()->donations()->create($this->data($r));ActivityService::log($r->user(),'created donation',$d);AlertService::send($r->user(),'Your donation was submitted and is ready for staff intake.', 'donation','normal',$d,'/donations');AlertService::sendToRoles(['staff','admin'],'A new donation requires warehouse processing.', 'donation','normal',$d,'/staff/inventory');return new DonationResource($d);} public function update(StoreDonationRequest $r,Donation $donation){abort_unless($donation->donor_id===$r->user()->id && $donation->status==='pending_match',403);$donation->update($this->data($r));ActivityService::log($r->user(),'updated donation',$donation);return new DonationResource($donation);} public function destroy(Request $r,Donation $donation){if(in_array($r->user()->role,['admin','staff'],true)){if($donation->image_path){\Illuminate\Support\Facades\Storage::disk('public')->delete($donation->image_path);}ActivityService::log($r->user(),'deleted donation',$donation);$donation->delete();return response()->noContent();}abort_unless($donation->donor_id===$r->user()->id && $donation->status==='pending_match',403);if($donation->image_path){\Illuminate\Support\Facades\Storage::disk('public')->delete($donation->image_path);}ActivityService::log($r->user(),'deleted donation',$donation);$donation->delete();return response()->noContent();} }
